components.css:
.ds-day-header { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 16px 20px; background: oklch(94% 0.008 70); border-bottom: 1px solid oklch(86% 0.008 70); }
.ds-day-title { font-family: 'Noto Serif TC', 'Source Han Serif TC', Georgia, serif; font-size: 22px; font-weight: 600; line-height: 1.2; letter-spacing: -0.01em; color: oklch(28% 0.01 70); margin: 0; }
.ds-day-chips { display: flex; gap: 8px; flex-shrink: 0; }
.ds-chip-info { display: inline-flex; align-items: center; gap: 6px; padding: 8px 14px; min-height: 44px; background: oklch(91% 0.008 70); color: oklch(48% 0.008 70); border: none; border-radius: 999px; font-family: -apple-system, BlinkMacSystemFont, 'Noto Sans TC', system-ui, sans-serif; font-size: 14px; font-weight: 500; cursor: pointer; transition: background 0.15s; }
.ds-chip-info:hover, .ds-chip-info:focus-visible { background: oklch(86% 0.008 70); outline: none; }
.ds-chip-icon { width: 18px; height: 18px; flex-shrink: 0; }

.ds-item-row { display: grid; grid-template-columns: 24px 60px 1fr 16px; column-gap: 12px; align-items: center; padding: 12px; border-radius: 10px; list-style: none; cursor: pointer; transition: background 0.15s; min-height: 56px; }
.ds-item-row:hover, .ds-item-row:focus-visible { background: oklch(91% 0.008 70); outline: none; }
.ds-item-current { background: oklch(94% 0.025 28); }
.ds-item-current .ds-item-time { color: oklch(45% 0.13 28); }
.ds-item-icon { width: 24px; height: 24px; color: oklch(48% 0.008 70); }
.ds-item-current .ds-item-icon { color: oklch(45% 0.13 28); }
.ds-item-time { font-family: -apple-system, BlinkMacSystemFont, 'Noto Sans TC', system-ui, sans-serif; font-size: 18px; font-weight: 600; line-height: 1.3; color: oklch(28% 0.01 70); font-variant-numeric: tabular-nums; }
.ds-item-content { display: flex; flex-direction: column; gap: 2px; min-width: 0; }
.ds-item-title { margin: 0; font-family: -apple-system, BlinkMacSystemFont, 'Noto Sans TC', system-ui, sans-serif; font-size: 16px; font-weight: 400; line-height: 1.5; color: oklch(28% 0.01 70); overflow: hidden; text-overflow: ellipsis; }
.ds-item-sub { margin: 0; font-family: inherit; font-size: 14px; font-weight: 400; line-height: 1.5; color: oklch(65% 0.008 70); }
.ds-item-chevron { width: 16px; height: 16px; color: oklch(78% 0.008 70); }

.ds-link-action { display: inline-flex; align-items: center; gap: 8px; padding: 12px 16px; min-height: 44px; background: oklch(94% 0.025 28); color: oklch(45% 0.13 28); border-radius: 10px; font-family: -apple-system, BlinkMacSystemFont, 'Noto Sans TC', system-ui, sans-serif; font-size: 16px; font-weight: 500; text-decoration: none; transition: background 0.15s, color 0.15s; }
.ds-link-action:hover, .ds-link-action:focus-visible { background: oklch(55% 0.13 28); color: oklch(97% 0.005 70); outline: none; }
.ds-link-icon { width: 18px; height: 18px; flex-shrink: 0; }

.ds-card-notes { padding: 16px; background: oklch(94% 0.008 70); color: oklch(48% 0.008 70); border-radius: 10px; font-family: -apple-system, BlinkMacSystemFont, 'Noto Sans TC', system-ui, sans-serif; font-size: 16px; font-weight: 400; line-height: 1.5; }
.ds-notes-line { margin: 0 0 12px 0; }
.ds-notes-line:last-child { margin-bottom: 0; }
.ds-notes-line strong { color: oklch(28% 0.01 70); font-weight: 600; }
.ds-notes-list { margin: 0; padding-left: 20px; list-style: disc; }
.ds-notes-list li { margin-bottom: 4px; }

.ds-day-indicator { position: fixed; left: 50%; bottom: calc(16px + env(safe-area-inset-bottom)); transform: translateX(-50%); display: flex; gap: 8px; padding: 8px 12px; background: oklch(97% 0.005 70 / 0.85); backdrop-filter: blur(8px); border-radius: 999px; border: 1px solid oklch(86% 0.008 70); z-index: 10; }
.ds-day-dot { width: 8px; height: 8px; padding: 0; background: oklch(78% 0.008 70); border: none; border-radius: 999px; cursor: pointer; transition: background 0.15s, transform 0.15s; position: relative; }
.ds-day-dot::after { content: ''; position: absolute; inset: -10px; }
.ds-day-dot:hover, .ds-day-dot:focus-visible { background: oklch(48% 0.008 70); outline: none; }
.ds-day-dot-active { background: oklch(55% 0.13 28); width: 24px; }

.ds-sheet-overlay { position: fixed; inset: 0; background: oklch(15% 0.01 70 / 0.55); z-index: 999; }
.ds-bottom-sheet { position: fixed; left: 0; right: 0; bottom: 0; max-height: 80vh; background: oklch(97% 0.005 70); border-radius: 20px 20px 0 0; z-index: 1000; display: flex; flex-direction: column; padding-top: 8px; }
.ds-grab-handle { width: 36px; height: 4px; background: oklch(86% 0.008 70); border-radius: 999px; margin: 0 auto 8px auto; }
.ds-sheet-content { flex: 1; overflow-y: auto; padding: 12px 20px calc(30px + env(safe-area-inset-bottom)); overscroll-behavior: contain; }
.ds-sheet-title { margin: 0 0 20px 0; font-family: -apple-system, BlinkMacSystemFont, 'Noto Sans TC', system-ui, sans-serif; font-size: 22px; font-weight: 600; line-height: 1.2; color: oklch(28% 0.01 70); }
.ds-sheet-section { display: flex; flex-direction: column; gap: 8px; margin-bottom: 24px; }
.ds-sheet-label { font-family: -apple-system, BlinkMacSystemFont, 'Noto Sans TC', system-ui, sans-serif; font-size: 14px; font-weight: 600; color: oklch(48% 0.008 70); }
@media (prefers-reduced-motion: reduce) { .ds-bottom-sheet, .ds-sheet-overlay { transition: none !important; } }
